(function(){const DESK=1180;function fit(screen,frame,least){const width=screen.clientWidth;const height=screen.clientHeight;const scale=width<least?1:Math.min(1,width/DESK);frame.style.width=width/scale+"px";frame.style.height=height/scale+"px";frame.style.transform=1===scale?"":"scale("+scale+")";}
const load=(frame)=>{if(!frame.src){frame.src=frame.dataset.src;}};document.querySelectorAll(".bb-try").forEach((section)=>{const small=section.querySelector(".bb-try__window");const dialog=section.querySelector(".bb-try__large");if(!small||!dialog){return;}
const smallScreen=small.querySelector(".bb-try__screen");const smallFrame=small.querySelector(".bb-try__frame");const largeScreen=dialog.querySelector(".bb-try__screen");const largeFrame=dialog.querySelector(".bb-try__frame");const fitSmall=()=>fit(smallScreen,smallFrame,0);fitSmall();new ResizeObserver(fitSmall).observe(smallScreen);const fitLarge=()=>fit(largeScreen,largeFrame,760);new ResizeObserver(fitLarge).observe(largeScreen);if("IntersectionObserver"in window){const watch=new IntersectionObserver((entries)=>{if(entries[0].isIntersecting){load(smallFrame);watch.disconnect();}},{rootMargin:"400px 0px"},);watch.observe(small);}else{load(smallFrame);}
small.addEventListener("click",()=>{load(largeFrame);dialog.showModal();document.documentElement.classList.add("has-bb-sheet");fitLarge();});const close=()=>dialog.close();dialog.querySelector(".bb-try__close").addEventListener("click",close);dialog.addEventListener("click",(event)=>{if(event.target===dialog){close();}});dialog.addEventListener("close",()=>{document.documentElement.classList.remove("has-bb-sheet");small.focus();});});})();